import{ax as a,A as i,aQ as l,z as t}from"./chunks/framework.BWRXlwpK.js";const e="/assets/image.B45d33so.png",n="/assets/image2.UYzEw6FD.png",b=JSON.parse('{"title":"Redis 介绍","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"redis/redis-intro.md","filePath":"redis/redis-intro.md","lastUpdated":1788243740000}'),p={name:"redis/redis-intro.md"};function d(o,s,r,h,c,u){return t(),i("div",null,s[0]||(s[0]=[l(`<h1 id="redis-介绍" tabindex="-1">Redis 介绍 <a class="header-anchor" href="#redis-介绍" aria-label="Permalink to &quot;Redis 介绍&quot;">​</a></h1><p>Redis 是一种高性能的内存数据库，通常被用作缓存、消息队列、会话存储以击实时数据处理。</p><p>它解决项目中的缓存问题</p><h2 id="redis-特点" tabindex="-1">Redis 特点 <a class="header-anchor" href="#redis-特点" aria-label="Permalink to &quot;Redis 特点&quot;">​</a></h2><p><strong>1.数据存储在内存中</strong></p><ul><li>读写速度非常快，通常可达到每秒几十万次操作。</li><li>适合需要高并发、低延迟的场景。</li></ul><p><strong>2.支持多种数据结构</strong></p><ul><li>String</li><li>Hash</li><li>List</li><li>Set</li><li>Sorted Set</li><li>Stream</li><li>Bitmap、HyperLogLog 等</li></ul><p><strong>3.支持持久化</strong></p><ul><li>虽然主要使用内存，但可以将数据保存到磁盘。</li><li>即使服务器重启，液能恢复数据。</li></ul><p><strong>4.支持发布订阅（Pub/Sub）</strong></p><ul><li>可一世先简单的消息队列功能。</li></ul><p><strong>5.支持分布式部署</strong></p><ul><li>Redis Cluster 提供数据分片和高可用能力</li></ul><h2 id="redis-常见用途" tabindex="-1">Redis 常见用途 <a class="header-anchor" href="#redis-常见用途" aria-label="Permalink to &quot;Redis 常见用途&quot;">​</a></h2><p><strong>1.缓存（最常见）</strong></p><p>数据库查询结果先放入Redis：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户请求</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Redis缓存</span></span>
<span class="line"><span>    ↓ (没有命中)</span></span>
<span class="line"><span>MySQL数据库</span></span></code></pre></div><p>这样可以减少数据库压力，提高系统响应速度。</p><p><strong>2.用户登陆状态（Session）</strong></p><p>存储用户登录信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET session:abc123 &quot;user1001&quot;</span></span>
<span class="line"><span>EXPIRE session:abc123 3600</span></span></code></pre></div><p>表示登录状态 1 小时后自动过期。</p><p><strong>3.计数器</strong></p><p>统计网站访问量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>INCR page:view</span></span></code></pre></div><p>每访问一次自动加 1。</p><p><strong>4.消息队列</strong></p><p>生产者：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LPUSH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task_queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;任务1&quot;</span></span></code></pre></div><p>消费者：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RPOP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task_queue</span></span></code></pre></div><h2 id="redis-与-mysql-的区别" tabindex="-1">Redis 与 MySQL 的区别 <a class="header-anchor" href="#redis-与-mysql-的区别" aria-label="Permalink to &quot;Redis 与 MySQL 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>Redis</th><th>MySQL</th></tr></thead><tbody><tr><td>存储位置</td><td>内存为主</td><td>磁盘为主</td></tr><tr><td>速度</td><td>非常快（微秒级）</td><td>较慢（毫秒级）</td></tr><tr><td>数据结构</td><td>丰富</td><td>关系型表</td></tr><tr><td>查询能力</td><td>简单 Key-Value</td><td>复杂 SQL</td></tr><tr><td>数据量</td><td>受内存限制</td><td>可存储海量数据</td></tr><tr><td>主要用途</td><td>缓存、实时数据</td><td>核心业务数据</td></tr></tbody></table><ul><li>MySQL = 仓库（容量大，但取货较慢）</li><li>Redis = 柜台（容量小，但取货极快）</li></ul><h2 id="主要内容" tabindex="-1">主要内容 <a class="header-anchor" href="#主要内容" aria-label="Permalink to &quot;主要内容&quot;">​</a></h2><ul><li>数据类型</li><li>命令</li><li>配置</li><li>持久化</li><li>管道</li><li>事务</li><li>分布式锁</li><li>主从复制</li><li>哨兵模式</li><li>集群</li><li>客户端</li><li>应用场景</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Redis基础命令</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Spring Boot整合Redis</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>缓存设计（穿透/击穿/雪崩）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Redis分布式锁</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Redis原理（RDB/AOF）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Redis集群</span></span></code></pre></div><h2 id="数据库架构发展" tabindex="-1">数据库架构发展 <a class="header-anchor" href="#数据库架构发展" aria-label="Permalink to &quot;数据库架构发展&quot;">​</a></h2><p>传统数据库的扩展性差（需要复杂的技术来实现），大数据下IO压力大（硬盘读写缓慢），表结构更改困难</p><p>发展流程：</p><ul><li>单库：最初的数据读写由单个数据库完成 <ul><li>随着访问量增加而出现性能问题</li></ul></li><li>缓存：数据访问量过高后，发展为将数据缓存到内存中，提高访问速度（内存读写远快于硬盘） <ul><li>通过缓存，缓解数据库的压力，优化数据结构和索引</li></ul></li><li>读写分离：访问量进一步增长，缓存也无法解决时，开始以读写分离的方式解决 <ul><li>数据写入压力增加，主从复制和读写的方案进入视野</li></ul></li><li>分库分表：访问量再次增长，开始再次分割数据库 <ul><li>主库的写压力过高，开始使用InnoDB引擎，以及分库技术</li></ul></li></ul><h2 id="单库架构和主从设计" tabindex="-1">单库架构和主从设计 <a class="header-anchor" href="#单库架构和主从设计" aria-label="Permalink to &quot;单库架构和主从设计&quot;">​</a></h2><p>单库架构三个阶段：</p><p>单服务器阶段所有的业务数据都存放在一个数据库中</p><p>分布式部署阶段，通过负载均衡流量分散到多台服务器上，但依旧访问一个数据库（这里之解决了服务器压力）</p><p>引入缓存，缓解数据库读写压力（在数据库前设置缓存处理，读压力变小）</p><p>主从设计:</p><p>进一步利用数据库的读写分离，在写入数据时，访问 <strong>主数据库（Master）</strong>，主数据库通过主从复制机制将数据更新同步到 <strong>从数据库（Slave）</strong>，这样当服务器读取数据时，就可以通过 <strong>从数据</strong> 库获得数据。</p><h2 id="主从设计的方式" tabindex="-1">主从设计的方式 <a class="header-anchor" href="#主从设计的方式" aria-label="Permalink to &quot;主从设计的方式&quot;">​</a></h2><p>垂直拆分：</p><p>为了各个业务模块相互不受影响，我们把应用层进行垂直拆分，即：把商品模块、订单模块、用户模块进行拆分，都单独作为一个应用系统，分别构建读写独立的数据库服务器，这样，当某个业务模块出现故障时，其他业务模块不受影响。</p><p><img src="`+e+'" alt="垂直拆分"></p><p>水平拆分：</p><p>MyCat 作为数据库中间件，可以帮助我们解决多个数据库不好管理的问题。只需要统一连接 MyCat 对外提供一个地址，而 MyCat 则帮这些项目练习所有后端的 MySQL 数据库。</p><p><img src="'+n+'" alt="alt text"></p><h2 id="nosql-分类" tabindex="-1">Nosql 分类 <a class="header-anchor" href="#nosql-分类" aria-label="Permalink to &quot;Nosql 分类&quot;">​</a></h2><ul><li>k-v：Memcache/Redis <ul><li>支持快速查找，常用于缓存</li></ul></li><li>列族：Hbase <ul><li>按列存储，方便结构化和压缩</li></ul></li><li>文档：MongoDB <ul><li>用类似json的格式存储，可以对某些字段建立索引</li></ul></li><li>图：Neo4j <ul><li>图形关系的解决方案</li></ul></li><li>...</li></ul><h2 id="cap-定理" tabindex="-1">CAP 定理 <a class="header-anchor" href="#cap-定理" aria-label="Permalink to &quot;CAP 定理&quot;">​</a></h2><p>一致性（Consistency）所有节点在同一时间具有相同的数据 可用性（Availability）保证每个请求不管成功或失败都有响应 分区容忍（Partition tolerance）系统中任意信息的丢失或失败不会影响系统的继续运作</p><p>CAP理论的核心是：一个分布式系统不可能同时很好的满足一致性，可用性和分区容忍这三个需求，最多只能同时较好的满足两个</p><p>CA - 单点集群，满足一致性，可用性的系统，通常在可扩展性上不太强大。 CP - 满足一致性，分区容忍性的系统，通常性能不是特别高 AP - 满足可用性和分区容忍性的系统，通常可能对一致性要求低一些</p>',62)]))}const k=a(p,[["render",d]]);export{b as __pageData,k as default};
